example.code:
// Registration
builder.Services.AddConcurrentSqliteDbContextFactory<AppDbContext>(
    "Data Source=app.db");

// Concurrent use — each task gets its own context
public async Task ProcessAllAsync(IEnumerable<int> ids, CancellationToken ct)
{
    var tasks = ids.Select(async id =>
    {
        await using var db = _factory.CreateDbContext();
        // ... read and write with db
    });
    await Task.WhenAll(tasks);
}

